sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var utils = new TimeTrackerUtils();

    // 1. Default Employee to current user if blank
    if (current.employee.nil()) {
        current.setValue('employee', gs.getUserID());
    }

    var empId = current.getValue('employee');

    // 2. Populate Team from employee's group membership whenever Team is blank
    if (current.team.nil() && empId) {
        var teams = utils._getUserTimeTrackerTeams(empId);
        if (teams && teams.length > 0) {
            current.setValue('team', teams.shift());
 // Must use teams (string), not the whole array
        }

    }

    // 3. Stamp Hourly Rate Snapshot & Calculated Cost
    var rate = utils.getUserHourlyRate(empId);
    var hrs = parseFloat(current.getValue('hours')) || 0;
    current.setValue('hourly_rate_snapshot', rate);
    current.setValue('calculated_cost', rate * hrs);

})(current, previous);
